<?php
namespace Tests\Unit;
use App\Core\Agents\Contracts\{CapabilityDecision,RiskLevel};use App\Core\Agents\Security\CapabilityPolicy;use PHPUnit\Framework\TestCase;
final class CapabilityPolicyTest extends TestCase {public function test_deny_outweighs_allow():void{$p=new CapabilityPolicy(allow:['connector.*'],deny:['connector.mail.*'],allowExternalWrites:true);self::assertSame(CapabilityDecision::Deny,$p->decide(RiskLevel::ExternalWrite,['tool'=>'connector.mail.send']));}public function test_destructive_never_becomes_silent():void{$p=new CapabilityPolicy(allow:['*'],allowDestructive:true);self::assertSame(CapabilityDecision::Ask,$p->decide(RiskLevel::Destructive,['tool'=>'connector.crm.delete']));}public function test_secrets_always_ask():void{$p=new CapabilityPolicy(allow:['*']);self::assertSame(CapabilityDecision::Ask,$p->decide(RiskLevel::Secrets,['tool'=>'secrets.read']));}}
